+__simt_callee__ inline void NormalizeFloatMantissa(uint32_t& mantissa, int& exponent)
+{
+    if (exponent != 0) {
+        mantissa |= 0x00800000U;
+        exponent -= 127;
+        return;
+    }
+    exponent = -126;
+    while ((mantissa & 0x00800000U) == 0U) {
+        mantissa <<= 1U;
+        --exponent;
+    }
